'use strict';
/* StrengthLab Beta v7. Editable reps, custom-group intelligence, serving-size food entry. */
const STORAGE_KEY='strengthlab-v1'; // Keep v1/v2 data on the same site URL.
const DAYS=['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const EMPTY_SPLIT=DAYS.map(name=>({name,muscles:[]}));
// Optional muscle-group names only. No exercise names are preloaded, suggested or restored.
const COMMON_MUSCLE_GROUPS=['Chest','Front & Side Delts','Biceps','Hamstrings','Lats','Lower Traps','Triceps','Rear Delts','Quads','Calves'];
const BASE_FOODS=[
 {id:'base-banana',name:'Banana',baseUnit:'g',kcal:89,c:22.8,p:1.1,f:.3},
 {id:'base-rice',name:'Cooked white rice',baseUnit:'g',kcal:130,c:28.2,p:2.7,f:.3},
 {id:'base-chicken',name:'Cooked chicken breast',baseUnit:'g',kcal:165,c:0,p:31,f:3.6},
 {id:'base-oatmeal',name:'Dry oatmeal',baseUnit:'g',kcal:389,c:66.3,p:16.9,f:6.9},
 {id:'base-ricecake',name:'Rice cakes',baseUnit:'g',kcal:387,c:81.5,p:8.2,f:2.8}
];
const MASS_UNITS=[['g','Grams'],['mg','Milligrams'],['kg','Kilograms'],['oz','Ounces'],['lb','Pounds'],['serving','Custom serving']];
const VOLUME_UNITS=[['ml','Milliliters'],['l','Liters'],['floz','US fluid ounces'],['cup','US cups'],['tbsp','Tablespoons'],['tsp','Teaspoons'],['pint','US pints'],['quart','US quarts'],['gallon','US gallons'],['serving','Custom serving']];
const UNIT_FACTOR={g:1,mg:.001,kg:1000,oz:28.349523125,lb:453.59237,ml:1,l:1000,floz:29.57352956,cup:236.5882365,tbsp:14.78676478,tsp:4.92892159,pint:473.176473,quart:946.352946,gallon:3785.411784};
const FLUID_TYPES=['Water','Sparkling water','Coffee','Tea','Milk','Juice','Soda','Protein shake','Sports drink','Electrolyte drink','Other'];
const $=id=>document.getElementById(id);
const escapeHtml=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(v,f=0)=>Number(Number(v||0).toFixed(f)).toLocaleString('en-US',{minimumFractionDigits:f,maximumFractionDigits:f});
const positive=v=>Number.isFinite(+v)&&+v>0;
const uid=()=>String(Date.now())+'-'+Math.random().toString(36).slice(2,9);
const lower=s=>String(s||'').toLocaleLowerCase('en-US').trim();
const sum=(arr,key)=>arr.reduce((t,o)=>t+(Number(o[key])||0),0);
const localToday=()=>{const d=new Date();return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`};
const dayIndex=date=>{const d=new Date(`${date}T12:00:00`);return Number.isNaN(d.valueOf())?0:d.getDay()};
const deepClone=o=>JSON.parse(JSON.stringify(o));
const defaults=()=>({themeHue:155,split:deepClone(EMPTY_SPLIT),muscleGroups:[],exerciseLibrary:{},archivedMuscles:[],archivedExercises:[],hiddenFoods:[],favorites:[],water:[],foods:[],sets:[],custom:[],workoutTemplates:DAYS.map(()=>[]),lastFluidType:'Water',customFluidName:'',recovery:{},weightUnit:'lb',massUnit:'g',volumeUnit:'ml',foodAmount:100,selectedDate:localToday(),day:dayIndex(localToday()),calGoal:null,proteinGoal:null,carbGoal:null,fluidGoal:null,bodyWeight:null,repMin:6,repMax:10,muscleRepRanges:{},insightMuscle:'all',insightExercise:'',selectedFoodId:'',meal:'Snack'});
function migrate(data){
 const d=defaults(),old=(data&&typeof data==='object'&&!Array.isArray(data))?data:{};
 const b={...d,...old};
 for(const k of ['sets','foods','custom','water','favorites','hiddenFoods','archivedMuscles','archivedExercises'])if(!Array.isArray(b[k]))b[k]=[];
 if(!b.recovery||typeof b.recovery!=='object'||Array.isArray(b.recovery))b.recovery={};
 if(!Array.isArray(b.workoutTemplates)||b.workoutTemplates.length!==7)b.workoutTemplates=DAYS.map(()=>[]);
 b.workoutTemplates=b.workoutTemplates.map((items,i)=>Array.isArray(items)?items.filter(x=>x&&typeof x.exercise==='string'&&x.exercise.trim()&&typeof x.muscle==='string').map((x,j)=>({id:String(x.id||'template-'+i+'-'+j),muscle:x.muscle,exercise:x.exercise,sets:Math.max(1,Math.min(12,Number(x.sets)||1))})):[]);
 if(!FLUID_TYPES.includes(b.lastFluidType))b.lastFluidType='Water';
 if(typeof b.customFluidName!=='string')b.customFluidName='';
 if(!Array.isArray(b.split)||b.split.length!==7)b.split=deepClone(EMPTY_SPLIT);
 b.split=b.split.map((x,i)=>({name:DAYS[i],muscles:Array.isArray(x.muscles)?x.muscles.filter(z=>typeof z==='string'&&z.trim()).map(z=>z.trim()):Array.isArray(x)?x.slice(1):[]}));
 b.custom=b.custom.map((f,i)=>({...f,id:f.id||'saved-'+i+'-'+lower(f.name).replace(/[^a-z0-9]/g,'-'),baseUnit:f.baseUnit==='ml'?'ml':'g',servingGrams:positive(f.servingGrams)?+f.servingGrams:100,servingAmount:positive(f.servingAmount)?+f.servingAmount:(positive(f.servingGrams)?+f.servingGrams:100),servingUnit:f.servingUnit||((f.baseUnit==='ml')?'ml':'g'),servingLabel:typeof f.servingLabel==='string'?f.servingLabel:''}));
 const allCatalog=[...BASE_FOODS,...b.custom];
 b.favorites=b.favorites.map(x=>allCatalog.find(f=>f.id===x||f.name===x)?.id||x);
 if(!Array.isArray(b.muscleGroups))b.muscleGroups=[...new Set([...Object.keys(b.exerciseLibrary||{}),...b.split.flatMap(x=>x.muscles),...b.sets.map(x=>x.muscle).filter(Boolean)])];
 else b.muscleGroups=[...new Set(b.muscleGroups.filter(Boolean))];
 b.muscleGroups=b.muscleGroups.filter(m=>!b.archivedMuscles.includes(m));
 if(!b.exerciseLibrary||typeof b.exerciseLibrary!=='object'||Array.isArray(b.exerciseLibrary))b.exerciseLibrary={};
 // Carry prior logged exercises into the library only on initial migration.
 if(!old.exerciseLibrary){for(const s of b.sets){if(!s.exercise||!s.muscle||b.archivedMuscles.includes(s.muscle))continue;const arr=b.exerciseLibrary[s.muscle]||[];if(!arr.some(x=>lower(x)===lower(s.exercise)))b.exerciseLibrary[s.muscle]=[...arr,s.exercise];}}
 for(const m of b.muscleGroups)if(!Array.isArray(b.exerciseLibrary[m]))b.exerciseLibrary[m]=[];
 // Preserve historical recovery data without pretending to know past bedtime / wake times.
 for(const s of b.sets)if(s.date&&!b.recovery[s.date]&&(positive(s.sleep)||s.precarbs!=null)){b.recovery[s.date]={bed:'',wake:'',legacyHours:positive(s.sleep)?+s.sleep:null,precarbs:Number(s.precarbs)||0,readiness:Number(s.readiness)||3,soreness:Number(s.soreness)||1,notes:''};}
 if(!/^\d{4}-\d{2}-\d{2}$/.test(b.selectedDate))b.selectedDate=localToday();
 // In v4 the selected calendar date, not an independent weekday toggle, determines the active day.
 b.day=dayIndex(b.selectedDate);
 if(b.selectedFoodId&&!allCatalog.some(f=>f.id===b.selectedFoodId)){const byName=allCatalog.find(f=>f.name===b.selectedFoodName);b.selectedFoodId=byName?.id||'';}
 if(!Number.isFinite(Number(b.repMin))||Number(b.repMin)<1)b.repMin=6;
 if(!Number.isFinite(Number(b.repMax))||Number(b.repMax)<b.repMin)b.repMax=Math.max(10,b.repMin);
 b.repMin=Math.max(1,Math.min(50,Math.round(b.repMin)));b.repMax=Math.max(b.repMin,Math.min(50,Math.round(b.repMax)));
 if(!b.muscleRepRanges||typeof b.muscleRepRanges!=='object'||Array.isArray(b.muscleRepRanges))b.muscleRepRanges={};
 if(typeof b.insightMuscle!=='string')b.insightMuscle='all';
 if(typeof b.insightExercise!=='string')b.insightExercise='';
 for(const k of ['calGoal','proteinGoal','carbGoal','fluidGoal','bodyWeight']){if(b[k]===undefined||b[k]===null||b[k]===''||!positive(b[k]))b[k]=null;else b[k]=Number(b[k]);}
 if(!Number.isFinite(Number(b.themeHue)))b.themeHue=155;
 b.themeHue=Math.min(360,Math.max(0,+b.themeHue));
 b.foodAmount=positive(b.foodAmount)?+b.foodAmount:0;
 return b;
}
let initial;try{initial=JSON.parse(localStorage.getItem(STORAGE_KEY)||'null')}catch{initial=null}
let db=migrate(initial);
let tab='today', foodMode='saved', activeScanner=null, cameraLoading=false, scannerHandled=false, toastTimer=null;
const ui={foodSearch:'',exerciseText:'',muscle:'',exerciseFocus:-1,exerciseSuggestions:[],foodFluidAmount:250,foodFluidUnit:'ml',liftLoad:'',workReps:0,workRir:-1,workRest:'',workRestNA:true,templateMuscle:'',templateExercise:'',templateSets:1,templateDraft:{},manualOpen:false,scannerStatus:''};
function resetWorkoutDraft(){ui.exerciseText='';ui.muscle='';ui.exerciseFocus=-1;ui.exerciseSuggestions=[];ui.liftLoad='';ui.workReps=0;ui.workRir=-1;ui.workRest='';ui.workRestNA=true;ui.templateDraft={};}
function persist(){try{localStorage.setItem(STORAGE_KEY,JSON.stringify(db))}catch(e){notify('Storage full or unavailable—export a backup.')}}
function notify(msg){const el=$('toast');el.textContent=msg;el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
function setTheme(){
 const hue=Math.max(0,Math.min(360,Number(db.themeHue)||0));
 const root=document.documentElement;
 root.style.setProperty('--hue',String(hue));
 // Set colors explicitly as well: Safari versions with older CSS color parsing
 // still respond to the picker, and all surface colors change together.
 const colors={
  '--bg':`hsl(${hue}, 32%, 8%)`, '--panel':`hsl(${hue}, 36%, 13%)`,
  '--panel2':`hsl(${hue}, 38%, 18%)`, '--input':`hsl(${hue}, 30%, 10%)`,
  '--line':`hsl(${hue}, 34%, 28%)`, '--muted':`hsl(${hue}, 13%, 70%)`,
  '--text':`hsl(${hue}, 16%, 96%)`, '--accent':`hsl(${hue}, 86%, 65%)`,
  '--accent-dark':`hsl(${hue}, 50%, 12%)`, '--accent-soft':`hsl(${hue}, 45%, 24%)`,
  '--ring':`hsla(${hue}, 86%, 65%, .35)`
 };
 for(const [k,v]of Object.entries(colors))root.style.setProperty(k,v);
 const meta=$('metaTheme');if(meta)meta.content=colors['--bg'];
 root.style.colorScheme='dark';
}
function currentFoods(){return db.foods.filter(x=>x.date===db.selectedDate)}
function currentSets(){return db.sets.filter(x=>x.date===db.selectedDate)}
function currentFluids(){return db.water.filter(x=>x.date===db.selectedDate)}
function weightFactor(){return db.weightUnit==='lb'?2.20462262185:1}
function displayWeight(kg){return n((Number(kg)||0)*weightFactor(),1)}
function sessionRecovery(date=db.selectedDate){return db.recovery[date]||{bed:'',wake:'',legacyHours:null,precarbs:null,readiness:null,soreness:null,notes:''}}
function sleepMinutes(bed,wake){if(!/^\d\d:\d\d$/.test(bed||'')||!/^\d\d:\d\d$/.test(wake||''))return null;const [bh,bm]=bed.split(':').map(Number),[wh,wm]=wake.split(':').map(Number);if(bh>23||wh>23||bm>59||wm>59)return null;return ((wh*60+wm)-(bh*60+bm)+1440)%1440}
function sleepText(minutes){if(minutes==null)return 'Not set';return `${Math.floor(minutes/60)}h ${String(minutes%60).padStart(2,'0')}m`}
function sleepHours(r){const mins=sleepMinutes(r.bed,r.wake);return mins!=null?mins/60:(positive(r.legacyHours)?+r.legacyHours:null)}
function hasGoal(key){return positive(db[key])}
function goalString(key,suffix=''){return hasGoal(key)?`${n(db[key])}${suffix}`:'Not set'}
function goalBar(value,key){return hasGoal(key)?`<div class="progress"><span style="width:${Math.min(100,Math.max(0,value/db[key]*100))}%"></span></div>`:''}
function caloriesOverview(mac,showRemaining=true){const g=hasGoal('calGoal');return `<div class="big">${n(mac.kcal)} <span class="small muted">${g?'/ '+n(db.calGoal)+' kcal':'kcal · no goal set'}</span></div>${goalBar(mac.kcal,'calGoal')}${showRemaining?`<p class="hint" style="margin:9px 0 0">${g?n(db.calGoal-mac.kcal)+' kcal remaining vs. your goal':'Set your calorie goal in Settings to see remaining calories.'}</p>`:''}`;}
function macroOverview(mac){return `<div class="grid3">${[['Protein',mac.p,'proteinGoal'],['Carbs',mac.c,'carbGoal'],['Fat',mac.f,null]].map(([name,value,key])=>`<div class="kpi"><div class="tag">${name}</div><div class="stat">${n(value)}g</div>${key&&hasGoal(key)?`<div class="bar" style="margin-top:7px"><span style="width:${Math.min(100,value/db[key]*100)}%"></span></div>`:''}<div class="hint">${key?goalString(key,'g goal'):'No goal set'}</div></div>`).join('')}</div>`;}
function repTarget(muscle){const own=db.muscleRepRanges?.[muscle];return own&&positive(own.min)&&positive(own.max)&&Number(own.max)>=Number(own.min)?{min:+own.min,max:+own.max}:{min:db.repMin,max:db.repMax};}
function groupOptions(){return [...new Set([...uniqueMuscles(),...db.sets.map(x=>x.muscle).filter(Boolean),...db.workoutTemplates.flat().map(x=>x.muscle).filter(Boolean)])].sort((a,b)=>a.localeCompare(b));}
function saveRepRange(muscle,min,max){if(!Number.isInteger(min)||!Number.isInteger(max)||min<1||max>50||min>max){notify('Choose a valid repetition range between 1 and 50.');return false;}if(muscle==='all'){db.repMin=min;db.repMax=max;}else{db.muscleRepRanges[muscle]={min,max};}persist();notify('✓ Repetition target updated');return true;}
function allFoods(){return [...BASE_FOODS,...db.custom]}
function availableFoods(){return allFoods().filter(f=>!db.hiddenFoods.includes(f.id))}
function foodById(id){return allFoods().find(f=>f.id===id)}
function foodBase(f){return f?.baseUnit==='ml'?'ml':'g'}
function validUnits(f){return foodBase(f)==='ml'?VOLUME_UNITS:MASS_UNITS}
function factorOfUnit(unit,f){if(unit==='serving')return positive(f.servingGrams)?+f.servingGrams:100;return UNIT_FACTOR[unit]||1}
function foodNutrition(f){const factor=db.foodAmount*factorOfUnit(db.servingUnit,f)/100;return {kcal:Math.max(0,(Number(f.kcal)||0)*factor),c:Math.max(0,(Number(f.c)||0)*factor),p:Math.max(0,(Number(f.p)||0)*factor),f:Math.max(0,(Number(f.f)||0)*factor)}}
function foodSorted(){const recentIds=[...db.foods].sort((a,b)=>String(b.date).localeCompare(String(a.date))).map(x=>x.foodId||allFoods().find(f=>f.name===x.name)?.id).filter(Boolean);const priority=[...new Set([...db.favorites,...recentIds])];return availableFoods().sort((a,b)=>{const ia=priority.indexOf(a.id),ib=priority.indexOf(b.id);if((ia>=0)!==(ib>=0))return ia>=0?-1:1;if(ia>=0&&ib>=0)return ia-ib;return a.name.localeCompare(b.name)});}
function unitText(u){return ({floz:'fl oz',serving:'serving',cup:'cup',tbsp:'tbsp',tsp:'tsp',ml:'mL',l:'L',g:'g',oz:'oz',kg:'kg',lb:'lb',mg:'mg',pint:'pint',quart:'quart',gallon:'gallon'})[u]||u}
function dailyDateInput(){const dateId=`sessionDate-${tab}`;return `<label class="label" for="${dateId}">Selected date</label><input type="date" id="${dateId}" value="${escapeHtml(db.selectedDate)}">`}
function shiftDateToWeekday(base,index){const d=new Date(base+'T12:00:00');d.setDate(d.getDate()+index-d.getDay());return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`}
function selectDate(next){if(!/^\d{4}-\d{2}-\d{2}$/.test(next)||next===db.selectedDate)return;db.selectedDate=next;db.day=dayIndex(next);resetWorkoutDraft();persist();render();}
function bindDate(){const e=$(`sessionDate-${tab}`);if(e)e.onchange=()=>selectDate(e.value)}
function e1rm(s){return (Number(s.kg)||0)*(1+(Number(s.reps)||0)/30)}
function sameExercise(s,m,ex){return lower(s.muscle)===lower(m)&&lower(s.exercise)===lower(ex)}
function statsFor(m,ex){const a=db.sets.filter(s=>sameExercise(s,m,ex)).sort((x,y)=>String(x.date).localeCompare(String(y.date))||String(x.id).localeCompare(String(y.id)));if(!a.length)return null;const best=a.reduce((x,y)=>e1rm(x)>=e1rm(y)?x:y),last=a[a.length-1];return {best,last,records:a.length}}
function exerciseList(m){return [...(db.exerciseLibrary[m]||[])].sort((a,b)=>a.localeCompare(b))}
function uniqueMuscles(){return db.muscleGroups.filter(m=>!db.archivedMuscles.includes(m)).sort((a,b)=>a.localeCompare(b))}
function dateBack(s,days){const d=new Date(s+'T12:00:00');d.setDate(d.getDate()-days);return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}-${String(d.getDate()).padStart(2,'0')}`;}
function volumeOf(arr){return arr.reduce((v,s)=>v+(Number(s.kg)||0)*(Number(s.reps)||0),0)}
function go(next){if(!['today','food','workout','recovery','insights','settings'].includes(next))return;if(tab==='food'&&next!=='food')stopScanner();tab=next;document.querySelectorAll('.tab-section').forEach(el=>el.classList.toggle('hidden',el.id!==next));document.querySelectorAll('.nav button').forEach(el=>{el.classList.toggle('active',el.dataset.tab===next);el.setAttribute('aria-current',el.dataset.tab===next?'page':'false')});render();window.scrollTo({top:0,behavior:'instant'});}
function render(){if(tab==='today')renderToday();if(tab==='food')renderFood();if(tab==='workout')renderWorkout();if(tab==='recovery')renderRecovery();if(tab==='insights')renderInsights();if(tab==='settings')renderSettings();}
const listen=(id,evt,fn)=>{const el=$(id);if(el)el.addEventListener(evt,fn)};
function renderToday(){
 const meals=currentFoods(),sets=currentSets(),fluids=currentFluids(),mac={kcal:sum(meals,'kcal'),p:sum(meals,'p'),c:sum(meals,'c'),f:sum(meals,'f')},water=sum(fluids,'ml');const r=sessionRecovery();const hrs=sleepHours(r);
 $('today').innerHTML=`<h2>Today</h2><div class="card hero"><div class="eyebrow">Daily nutrition</div>${caloriesOverview(mac)}</div>
 ${macroOverview(mac)}
 <div class="card stack" style="margin-top:13px">${dailyDateInput()}<h3 style="margin-bottom:0">Selected week · tap a day</h3><div class="grid7">${db.split.map((d,i)=>`<button class="daybtn ${db.day===i?'active':''}" data-day="${i}" aria-label="Show ${d.name}"><span class="glyph">${d.muscles.length?'◆':'☾'}</span>${d.name.slice(0,3)}<span class="daynum">${Number(shiftDateToWeekday(db.selectedDate,i).slice(-2))}</span></button>`).join('')}</div><div class="row"><strong>${escapeHtml(db.split[db.day].name)} · ${escapeHtml(db.selectedDate)}</strong><span class="pill">${db.split[db.day].muscles.length?'Training':'Recovery day'}</span></div><div class="hint">${escapeHtml(db.split[db.day].muscles.join(' · ')||'No muscle groups scheduled. Customize your split in Settings.')}</div>${db.split.every(d=>d.muscles.length===0)?'<button class="btn secondary" id="setupSplit">Set up your training split</button>':''}<div class="grid"><div class="kpi"><div class="tag">Working sets</div><div class="stat">${sets.length}</div></div><div class="kpi"><div class="tag">Training volume</div><div class="stat">${n(volumeOf(sets)*weightFactor())}</div><div class="hint">${db.weightUnit} × reps</div></div></div><div class="buttons"><button class="btn secondary" id="quickFood">+ Food</button><button class="btn" id="quickWorkout">+ Set</button></div></div>
 <div class="grid"><div class="card"><div class="tag">Total fluids</div><div class="stat">${n(water)} <span class="small">mL</span></div>${goalBar(water,'fluidGoal')}<button class="btn small secondary" style="width:100%;margin-top:10px" id="quickWater">+ 250 mL</button></div><div class="card"><div class="tag">Last sleep</div><div class="stat">${hrs==null?'—':sleepText(Math.round(hrs*60))}</div><div class="hint">Pre-workout carbs: ${r.precarbs==null?'—':n(r.precarbs)+'g'}</div><button class="btn small secondary" style="width:100%;margin-top:10px" id="quickRecovery">Edit recovery</button></div></div><p class="hint">Data reflects the selected date. Training volume counts logged working sets and is not a direct measure of hypertrophy.</p>`;
 bindDate();document.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>selectDate(shiftDateToWeekday(db.selectedDate,Number(b.dataset.day))));listen('setupSplit','click',()=>go('settings'));listen('quickFood','click',()=>go('food'));listen('quickWorkout','click',()=>go('workout'));listen('quickRecovery','click',()=>go('recovery'));listen('quickWater','click',()=>addFluid(250,'Water','ml'));
}
function renderFoodRows(){
 const el=$('foodResults');if(!el)return;
 const query=lower(ui.foodSearch);const matches=foodSorted().filter(f=>lower(f.name).includes(query));
 el.innerHTML=matches.length?matches.map(f=>`<div class="listitem row"><button class="btn secondary" style="text-align:left;flex:1;min-width:0;padding:10px" data-food-select="${escapeHtml(f.id)}"><strong>${escapeHtml(f.name)}</strong><div class="hint">${n(f.kcal*(positive(f.servingGrams)?f.servingGrams:100)/100)} kcal / ${f.servingLabel?escapeHtml(f.servingLabel)+' · ':''}${n(f.servingAmount||f.servingGrams||100)} ${unitText(f.servingUnit||foodBase(f))} ${db.selectedFoodId===f.id?'· Selected':''}</div></button><button class="btn icon secondary" data-food-favorite="${escapeHtml(f.id)}" aria-label="${db.favorites.includes(f.id)?'Remove favorite':'Add favorite'}">${db.favorites.includes(f.id)?'★':'☆'}</button><button class="btn icon ghost" data-food-hide="${escapeHtml(f.id)}" aria-label="Remove saved food">×</button></div>`).join(''):'<p class="hint">No matching foods. Add one in the Custom tab or scan a product.</p>';
 el.querySelectorAll('[data-food-select]').forEach(b=>b.onclick=()=>{db.selectedFoodId=b.dataset.foodSelect;const selected=foodById(db.selectedFoodId);db.servingUnit='serving';db.foodAmount=1;persist();renderFood();notify(selected.name+' selected')});
 el.querySelectorAll('[data-food-favorite]').forEach(b=>b.onclick=()=>{const id=b.dataset.foodFavorite;db.favorites=db.favorites.includes(id)?db.favorites.filter(x=>x!==id):[id,...db.favorites];persist();renderFoodRows();notify(db.favorites.includes(id)?'Added to favorites':'Removed from favorites')});
 el.querySelectorAll('[data-food-hide]').forEach(b=>b.onclick=()=>{const id=b.dataset.foodHide;const f=foodById(id);if(!f||!confirm('Remove "'+f.name+'" from your food selection list? Existing diary entries will remain.'))return;if(id.startsWith('base-'))db.hiddenFoods=[...db.hiddenFoods,id];else db.custom=db.custom.filter(x=>x.id!==id);db.favorites=db.favorites.filter(x=>x!==id);if(db.selectedFoodId===id){db.selectedFoodId='';db.foodAmount=0;}persist();renderFood();notify('Saved food removed')});
}
function servingMax(unit){return ({g:1000,mg:500000,kg:5,oz:36,lb:5,ml:1500,l:5,floz:48,cup:8,tbsp:50,tsp:150,pint:8,quart:5,gallon:2,serving:10})[unit]||1000}
