async function lookupBarcode(code){
 code=String(code||'').trim();if(!code)return notify('Enter a barcode first.');if(!/^\d{8,14}$/.test(code))return notify('Scanned QR content is not a UPC/EAN food barcode. Enter an 8–14 digit product code.');
 notify('Looking up barcode…');try{const url='https://world.openfoodfacts.org/api/v2/product/'+encodeURIComponent(code)+'.json?fields=code,product_name,nutriments,quantity,serving_size';const response=await fetch(url,{headers:{Accept:'application/json'}});if(!response.ok)throw new Error('Network error');const data=await response.json();if(data.status!==1||!data.product)throw new Error('Product not found');const product=data.product,nutr=product.nutriments||{};const liquid=['energy-kcal_100ml','carbohydrates_100ml','proteins_100ml','fat_100ml'].some(key=>nutr[key]!=null);const suffix=liquid?'_100ml':'_100g';const item={id:'scan-'+code,name:product.product_name?.trim()||'Product '+code,baseUnit:liquid?'ml':'g',servingGrams:100,kcal:Number(nutr['energy-kcal'+suffix])||0,c:Number(nutr['carbohydrates'+suffix])||0,p:Number(nutr['proteins'+suffix])||0,f:Number(nutr['fat'+suffix])||0,barcode:code};const prev=db.custom.findIndex(f=>f.barcode===code||f.id===item.id);if(prev>=0)db.custom[prev]={...db.custom[prev],...item};else db.custom.push(item);db.hiddenFoods=db.hiddenFoods.filter(id=>id!==item.id);db.selectedFoodId=item.id;db.servingUnit='serving';db.foodAmount=1;ui.foodSearch='';foodMode='saved';await stopScanner();persist();renderFood();notify('✓ Product saved. Check nutrition label.')}catch(err){notify('Lookup failed: '+err.message+'. Try Custom food.');}
}
function scannerStatus(message,kind='info'){ui.scannerStatus=message;const el=$('scanStatus');if(el){el.textContent=message;el.dataset.kind=kind;}}
const SCANNER_URLS=['https://cdn.jsdelivr.net/npm/html5-qrcode@2.3.8/html5-qrcode.min.js','https://cdnjs.cloudflare.com/ajax/libs/html5-qrcode/2.3.8/html5-qrcode.min.js','https://unpkg.com/html5-qrcode@2.3.8/html5-qrcode.min.js'];
function loadScannerScript(src){return new Promise((resolve,reject)=>{const script=document.createElement('script');const timeout=setTimeout(()=>{script.remove();reject(new Error('Scanner library timed out'));},10000);script.src=src;script.async=true;script.onload=()=>{clearTimeout(timeout);resolve()};script.onerror=()=>{clearTimeout(timeout);reject(new Error('Scanner download blocked'))};document.head.appendChild(script)})}
async function ensureScannerLibrary(){if(window.Html5Qrcode)return;for(const url of SCANNER_URLS){try{await loadScannerScript(url);if(window.Html5Qrcode)return}catch(err){/* Try next origin */}}throw new Error('Unable to load barcode reader. Check connection/content blockers and try manual entry.')}
async function stopScanner(){cameraLoading=false;const instance=activeScanner;activeScanner=null;if(!instance)return;try{if(instance.isScanning)await instance.stop()}catch{}try{await instance.clear()}catch{}}
async function onDetectedBarcode(value){if(scannerHandled)return;scannerHandled=true;const code=String(value||'').trim();await stopScanner();const field=$('barcode');if(field)field.value=code;scannerStatus('Read code: '+code);notify('✓ Barcode detected');if(/^\d{8,14}$/.test(code))await lookupBarcode(code);else scannerStatus('A QR code was found, but the food database needs a numeric UPC/EAN barcode.','warning');}
async function startScanner(){
 if(cameraLoading||activeScanner)return;
 if(!window.isSecureContext)return scannerStatus('Live camera needs HTTPS. Open the GitHub Pages URL in Safari.','warning');
 if(!navigator.mediaDevices?.getUserMedia)return scannerStatus('Live camera is unavailable in this browser. Take a photo or choose a file instead.','warning');
 cameraLoading=true;scannerHandled=false;scannerStatus('Loading barcode reader…');
 try{
  await ensureScannerLibrary();
  if(foodMode!=='scan'||tab!=='food')return;
  const target=$('cameraScanner');if(!target)throw new Error('Scanner view unavailable');target.innerHTML='';
  const scanner=new window.Html5Qrcode('cameraScanner',{verbose:false});activeScanner=scanner;
  try{await scanner.start({facingMode:'environment'},{fps:8,qrbox:{width:220,height:150}},onDetectedBarcode,()=>{});}
  catch(firstError){try{await scanner.start({facingMode:'environment'},{fps:8},onDetectedBarcode,()=>{});}catch{throw firstError}}
  scannerStatus('Camera active. Hold a barcode steady inside the frame.');
 }catch(err){await stopScanner();const text=String(err?.name||'')+' '+String(err?.message||err);const msg=/permission|notallowed|denied/i.test(text)?'Camera permission denied. In Safari, open website settings and allow camera, then try again.':'Camera could not start: '+text.slice(0,150)+'. Try Take a photo or manual entry.';scannerStatus(msg,'warning');notify('Camera not available');}
 finally{cameraLoading=false}
}
async function scanPhoto(file){
 if(!file)return;scannerHandled=false;scannerStatus('Reading image: '+file.name+'…');
 try{
  await stopScanner();
  // Native BarcodeDetector handles photos without downloading a JavaScript scanner when supported.
  if('BarcodeDetector' in window){try{const detector=new window.BarcodeDetector({formats:['ean_13','ean_8','upc_a','upc_e','code_128','qr_code']});const url=URL.createObjectURL(file);try{const img=new Image();img.src=url;await img.decode();const results=await detector.detect(img);if(results.length&&results[0].rawValue){await onDetectedBarcode(results[0].rawValue);return;}}finally{URL.revokeObjectURL(url)}}catch{/* Fall back to ZXing-backed reader */}}
  await ensureScannerLibrary();
  if(foodMode!=='scan'||tab!=='food')return;
  const el=$('cameraScanner');if(!el)throw new Error('Scanner view unavailable');el.innerHTML='';
  const scanner=new window.Html5Qrcode('cameraScanner',{verbose:false});activeScanner=scanner;
  const code=await scanner.scanFile(file,true);
  await onDetectedBarcode(code);
 }catch(err){scannerStatus('Could not detect a barcode in this photo. Use a clear, focused image with the whole barcode visible, or enter the digits manually.','warning');notify('No readable barcode detected');await stopScanner();}
}
function folderMarkup(m){const items=exerciseList(m);return `<details class="folder" data-muscle-folder="${escapeHtml(m)}"><summary><span>${escapeHtml(m)}</span><span class="hint">${items.length} exercises ⌄</span></summary><div style="margin-top:12px" class="stack"><div class="row"><span class="hint">Saved exercises • tap Log to use</span><button class="btn small ghost" data-add-group-exercise="${escapeHtml(m)}">+ Exercise</button></div><div id="newExerciseArea-${encodeURIComponent(m)}"></div>${items.length?items.map(ex=>{const st=statsFor(m,ex);return `<div class="mini"><div class="row start"><strong>${escapeHtml(ex)}</strong><button class="btn small ghost" data-remove-exercise="${escapeHtml(m)}" data-ex-name="${escapeHtml(ex)}" aria-label="Remove saved exercise">×</button></div><div class="hint" style="margin:6px 0">${st?`Estimated PR: <strong>${displayWeight(e1rm(st.best))} ${db.weightUnit} e1RM</strong> · ${displayWeight(st.best.kg)} × ${n(st.best.reps)} reps<br>Last session: ${escapeHtml(st.last.date)} · ${displayWeight(st.last.kg)} ${db.weightUnit} × ${n(st.last.reps)} · ${n(st.last.rir)} RIR`:'Estimated PR: —<br>Last session: —'}</div><button class="chip" data-select-exercise="${escapeHtml(ex)}" data-select-muscle="${escapeHtml(m)}">Log this exercise</button></div>`}).join(''):'<p class="hint">No exercises yet. Add your first exercise above.</p>'}</div></details>`;}
function addExercise(m,name){name=String(name||'').trim();if(!m||!name)return notify('Enter an exercise name.');const arr=db.exerciseLibrary[m]||[];if(arr.some(x=>lower(x)===lower(name)))return notify('That exercise is already in this muscle group.');db.exerciseLibrary[m]=[...arr,name];db.archivedExercises=db.archivedExercises.filter(x=>x!==m+'|'+lower(name));persist();notify('✓ Exercise added');renderWorkout();const folder=[...document.querySelectorAll('[data-muscle-folder]')].find(x=>x.dataset.muscleFolder===m);if(folder)folder.open=true;}
